function hazard(text) {
 const s=text.toLowerCase().split(/[.!?;\n]+/);
 return s.some(x=>! /\b(no|without|sin|not)\b/.test(x) && /sparks?|sparking|burning|smoke|gas smell|smell of gas|olor a gas|quemado|humo|chispas|electric shock|exposed wire|flooding|inundaci/.test(x));
}
export function analyze(text, selected='auto') {
 text=String(text).trim(); if(text.length<20) throw new Error('Please describe the job in at least 20 characters.'); if(text.length>6000) throw new Error('Please keep the description under 6,000 characters.');
 const key=selected==='auto' ? ['design','business','automation','software','pool','irrigation','electrical','plumbing','renovation'].find(k=>trades[k].re?.test(text))||'general' : (trades[selected]?selected:'general');
 const t=trades[key], emergency=hazard(text), urgent= /leak|wet|tripped|no water|fuga|pierde|sin agua/i.test(text);
 const urgency=emergency?'Immediate safety review':urgent?'Priority visit': /production down|outage|data loss|ca[ií]da|p[eé]rdida de datos/i.test(text)?'Priority visit':'Routine assessment';
 const safety=emergency?'Keep clear of the affected area. Do not touch or operate unsafe equipment. If there is an immediate threat, leave the area and contact local emergency services. Arrange a qualified specialist.':'Provisional assessment only. Stop using equipment if symptoms worsen or a hazard appears. A competent professional must confirm scope and any proposed cause before action.';
 const summary=`${t.name} request: ${text.length>260?text.slice(0,257)+'…':text}`;
 return {schemaVersion:1,trade:key,category:t.name,summary,originalRequest:text,problem:t.problem,urgency,safety,materials:t.materials,questions:t.questions,steps:emergency?['Stop using the affected equipment and keep clear.','Arrange urgent assessment by a qualified specialist.','Confirm safety before any inspection or repair.']:t.steps,response:`Hello, thank you for the details. We have noted your ${t.name.toLowerCase()} request. ${emergency?'Please keep clear of the affected equipment and arrange urgent specialist assessment. ':''}Before we confirm the work, please confirm the following: ${t.questions[0]} We can then arrange an assessment and provide an itemised estimate. Resources and final pricing will be confirmed after reviewing the scope.`,engine:'Rule-based triage — not AI diagnosis'};
}
export function estimate({hours,rate,materials,callout,tax}) {
 const values=[hours,rate,materials,callout,tax].map(Number);
 if(values.some(x=>!Number.isFinite(x)||x<0)||values[4]>100) throw new Error('Enter valid non-negative amounts; tax must be 0–100%.');
 const [h,r,m,c,t]=values, subtotal=Math.round((h*r+m+c)*100)/100, vat=Math.round(subtotal*t)/100;
 return {hours:h,rate:r,materials:m,callout:c,tax:t,subtotal,taxAmount:vat,total:Math.round((subtotal+vat)*100)/100};
}
